import gradio as gr, torch, torch.nn as nn
from transformers import AutoTokenizer

tok = AutoTokenizer.from_pretrained("distilbert/distilbert-base-uncased")
class MLP(nn.Module):
    def __init__(self): super().__init__(); self.emb = nn.Embedding(30522, 32); self.fc = nn.Linear(32, 2)
    def forward(self, x): return self.fc(self.emb(x).mean(dim=1))
net = MLP().eval()

def predict_sentiment(text):
    ids = tok(text, return_tensors="pt")["input_ids"]
    with torch.no_grad():
        probs = torch.softmax(net(ids), dim=-1)[0]
    return {"Negative": float(probs[0]), "Positive": float(probs[1])}

demo = gr.Interface(fn=predict_sentiment, inputs=gr.Textbox(value="This movie was pure cinematic poetry!"), outputs=gr.Label(), title="PyTorch Custom Neural Network Classifier")
demo.launch()

