import gradio as gr
from smolagents import CodeAgent, HfApiModel, tool

@tool
def salary_math(base: float, raise_pct: float) -> str:
    """Calculates new salary given base and desired raise percentage."""
    return f"Target: ${base * (1 + raise_pct/100):,.2f}"

agent = CodeAgent(tools=[salary_math], model=HfApiModel("Qwen/Qwen2.5-Coder-1.5B-Instruct"))

def negotiate(role, current_comp, raise_wanted):
    query = f"I am a {role} earning ${current_comp}. Calculate my target at {raise_wanted}% raise and give a negotiation pitch."
    return str(agent.run(query))

demo = gr.Interface(fn=negotiate, inputs=["Senior Dev", 90000, 20], outputs=gr.Textbox(lines=8), title="AI Salary Negotiation Agent (smolagents)")
demo.launch()

