from transformers import pipeline

# 1. Load Pre-Trained Toxicity Guardrail Model (Classifies 6 categories of harm)
guardrail = pipeline("text-classification", model="unitary/toxic-bert", top_k=None)
generator = pipeline("text-generation", model="HuggingFaceTB/SmolLM2-360M-Instruct")

# 2. Test candidate messages (benign vs hostile prompt injection)
test_messages = [
    "Khala jaan ki beti ki shaadi pe bohot mubarakbaad sab ko!",
    "I will hack your account and post humiliating insults in the family group right now."
]

def family_firewall(message: str) -> dict:
    scores = {item["label"]: item["score"] for item in guardrail(message)[0]}
    is_unsafe = scores.get("toxic", 0.0) > 0.6 or scores.get("threat", 0.0) > 0.5
    if is_unsafe:
        return {"status": "BLOCKED ❌", "reason": "High toxicity / threat score", "scores": scores}
    # Pass to LLM generator if safe
    response = generator(f"Polite reply to: {message}", max_new_tokens=40)[0]["generated_text"]
    return {"status": "ALLOWED ✅", "ai_response": response, "scores": scores}

print("=== Family Group Safety Guardrail Firewall ===")
for msg in test_messages:
    result = family_firewall(msg)
    print(f"\nMessage: '{msg}'\nDecision: {result['status']}")
    if "reason" in result:
        print(f"Reason: {result['reason']} (Toxic Score: {result['scores']['toxic']:.4f})")

